//@formatter:on
public class VSCodeIntegrationOptionsPlugin : Plugin, ApplicationLevelOnlyPlugin {

	public static readonly string PLUGIN_OPTIONS_NAME = "Visual Studio Code Integration";

	public static readonly string VSCODE_EXE_PATH_OPTION = "Visual Studio Code Executable Path";
	private static readonly string VSCODE_EXE_PATH_DESC = "Full path to Visual Studio Code executable";
	private static readonly File VSCODE_EXE_PATH_DEFAULT = getDefaultVSCodeExecutable();

	public static readonly string VSCODE_ARG1_OPTION =
		"Visual Studio Code Launch Argument 1 (optional)";
	private static readonly string VSCODE_ARG1_DESC =
		"Optional argument 1 for Visual Studio Code executable";
	private static readonly string VSCODE_ARG1_DEFAULT = null;

	public static readonly string VSCODE_ARG2_OPTION =
		"Visual Studio Code Launch Argument 2 (optional)";
	private static readonly string VSCODE_ARG2_DESC =
		"Optional argument 2 for Visual Studio Code executable";
	private static readonly string VSCODE_ARG2_DEFAULT = null;

	public VSCodeIntegrationOptionsPlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	public void init() {
		base.init();
		ToolOptions options = tool.getOptions(PLUGIN_OPTIONS_NAME);
		options.registerOption(VSCODE_EXE_PATH_OPTION, OptionType.FILE_TYPE,
			VSCODE_EXE_PATH_DEFAULT, null, VSCODE_EXE_PATH_DESC);
		options.registerOption(VSCODE_ARG1_OPTION, OptionType.STRING_TYPE,
			VSCODE_ARG1_DEFAULT, null, VSCODE_ARG1_DESC);
		options.registerOption(VSCODE_ARG2_OPTION, OptionType.STRING_TYPE,
			VSCODE_ARG2_DEFAULT, null, VSCODE_ARG2_DESC);
		options.setOptionsHelpLocation(
			new HelpLocation("VSCodeIntegration", "VSCodeIntegrationOptions"));
	}

	/**
	 * {@return the default Visual Studio Code executable location for the current platform}
	 */
	private static File getDefaultVSCodeExecutable() {
		switch (OperatingSystem.CURRENT_OPERATING_SYSTEM) {
			case WINDOWS:
				File local = new File(System.getenv("LOCALAPPDATA"),
					"Programs/Microsoft VS Code/bin/code.cmd");
				File admin =
					new File(System.getenv("PROGRAMFILES"), "Microsoft VS Code/bin/code.cmd");
				return admin.exists() ? admin : local;
			case MAC_OS_X:
				return new File("/Applications/Visual Studio Code.app/Contents/MacOS/Electron");
			case LINUX:
				return new File("/usr/bin/code");
			default:
				return null;
		};
	}
}
